/**
 * @suppress
 */
public object FfiConverterMapStringTypeArgWire: FfiConverterRustBuffer<Map<kotlin.String, ArgWire>> {
    override fun read(buf: ByteBuffer): Map<kotlin.String, ArgWire> {
        val len = buf.getInt()
        return buildMap<kotlin.String, ArgWire>(len) {
            repeat(len) {
                val k = FfiConverterString.read(buf)
                val v = FfiConverterTypeArgWire.read(buf)
                this[k] = v
            }
        }
    }

    override fun allocationSize(value: Map<kotlin.String, ArgWire>): ULong {
        val spaceForMapSize = 4UL
        val spaceForChildren = value.map { (k, v) ->
            FfiConverterString.allocationSize(k) +
            FfiConverterTypeArgWire.allocationSize(v)
        }.sum()
        return spaceForMapSize + spaceForChildren
    }

    override fun write(value: Map<kotlin.String, ArgWire>, buf: ByteBuffer) {
        buf.putInt(value.size)
        // The parens on `(k, v)` here ensure we're calling the right method,
        // which is important for compatibility with older android devices.
        // Ref https://blog.danlew.net/2017/03/16/kotlin-puzzler-whose-line-is-it-anyways/
        value.forEach { (k, v) ->
            FfiConverterString.write(k, buf)
            FfiConverterTypeArgWire.write(v, buf)
        }
    }
}



