        /**
         * Translates a view-model message into `locale` with the web catalogs, strictly:
         * a missing key, argument or locale is an error, never a fallback (D3).
         */
    @Throws(FfiException::class) fun `translate`(`locale`: kotlin.String, `message`: Msg): kotlin.String {
            return FfiConverterString.lift(
    uniffiRustCallWithError(FfiException) { _status ->
    UniffiLib.uniffi_transgate_ffi_fn_func_translate(
    
        
        FfiConverterString.lower(`locale`),
        FfiConverterTypeMsg.lower(`message`),_status)
}
    )
    }
    

        /**
         * The UI locales, in catalog order.
         */ fun `uiLocales`(): List<kotlin.String> {
            return FfiConverterSequenceString.lift(
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_transgate_ffi_fn_func_ui_locales(
    
        _status)
}
    )
    }
    


